### VariableSource (ZipVariableSource.java)

```java
import java.io.File;
import java.io.IOException;
import java.util.Enumeration;
import java.util.Map;
import java.util.Properties;
import java.util.regex.Pattern;

public class ZipVariableSource extends MapVariableSource {

    private final String zipFilePath;
    private Properties properties;

    public ZipVariableSource(String zipFilePath) {
        super(null);
        this.zipFilePath = zipFilePath;
    }

    @Override
    public Map<String, String> load() {
        Map<String, String> variables = super.load();
        variables.putAll(getVariablesFromFile(zipFilePath));
        return variables;
    }

    private Map<String, String> getVariablesFromFile(String filePath) {
        Map<String, String> variables = super.load();
        try {
            File propertiesFile = new File(filePath);
            if (!propertiesFile.exists()) {
                throw new IOException("Properties file not found at: " + propertiesFile.getAbsolutePath());
            }
            Properties properties = new Properties();
            properties.load(this::getInputStreamProperties);
            variables.putAll(toMap(properties));
        } catch (IOException e) {
            System.err.println("Failed to load variables from file: " + filePath);
            e.printStackTrace();
        }
        return variables;
    }

    private InputStream getInputStreamProperties(String propertyName) {
        try {
            return new Properties().load(new File(zipFilePath).getInputStream());
        } catch (IOException e) {
            // Ignore if property not found
            return null;
        }
    }

    private Map<String, String> toMap(Properties properties) {
        Map<String, String> variables = new java.util.LinkedHashMap<String, String>();
        for (Enumeration enumeration = properties.keys(); enumeration.hasMoreElements(); ) {
            String key = enumeration.nextElement().toString();
            variables.put(Pattern.compile("\\.").matcher(key).replaceFirst("."), properties.getProperty(key));
        }
        return variables;
    }
}
```

