      case _ => // Implementierung für Merkmal 3
      case _ => // Implementierung für Merkmal 4
      case _ => // Implementierung für Merkmal 5
    }
  }
}

// Subklasse für die Verarbeitung der Datensätze von Merkmal 1
class RomanNumeralM1(value: String) extends RomanNumeral {
  require(value.matches("\\d+"), "Wert für Merkmal 1 muss eine positive ganze Zahl sein")
  private val decimalValue = BigInteger(value)

  override def toDecimal: BigInteger = decimalValue
}

// Subklasse für die Verarbeitung der Datensätze von Merkmal 2
class RomanNumeralM2(value: String) extends RomanNumeral {
  require(value.matches("IV|IX|XL|XC|CD|CM"), "Wert für Merkmal 2 muss eine wahlweise gültige römische Zahl sein (IV, IX, XL, XC, CD, CM)")
  private val romanValue = value
  private val decimalValue = {
    romanValue match {
      case "IV"   => 4
      case "IX"   => 9
      case "XL"   => 40
      case "XC"   => 90
      case "CD"   => 400
      case "CM"   => 900
      case _      => require(false, "Wert für Merkmal 2 ist keine gültige römische Zahl"), 0
    }
  }.toBigInt

  override def toDecimal: BigInteger = decimalValue
}

// Subklasse für die Verarbeitung der Datensätze von Merkmal 3 bis 5 (gemäß den Befehlsgrenzen)
class RomanNumeralM3_5(value: String) extends RomanNumeral {
  require(value.matches("[IVX]+") || value.matches("[XLCD]+") || value.matches("[XMCD]+"), "Wert für Merkmale 3-5 muss eine gültige römische Zahl sein (max. Befehlsgrenzen I...IX, X...XC, C...CM)")
  private val romanValue = value
  private val decimalValue = {
    def romanToDecimal(roman: String): Int = {
      roman match {
        case "I"   => 1
        case "V"   => 5
        case "X"   => 10
        case "L"   => 50
        case "C"   => 100
        case "D"   => 500
        case "M"   => 1000
        case _     => require(false, "Wert für Merkmale 3-5 ist keine gültige römische Zahl"), 0
      }
    }

    def sum(roman: String,beiten: Map[Char, Int]): Int = {
      roman.toCharArray
        .reverse
        .foldLeft(0) { (acc, c) =>
          val currentValue = aktionen(c)
          if (cätten.contains(c)) {
            val prevValue = aktionen(prev(c).toString.charAt(0))
            if (prevValue < currentValue) acc + (currentValue - prevValue * 2)
            else acc + currentValue
          } else acc + currentValue
        }
    }

    val digitValue = romanValue.reverse.map(romanToDecimal(_)).toArray
    val subtractionValues = List((1000, 900), (900, 800), (500, 400), (400, 300), (100, 90), (90, 80), (50, 40), (40, 30), (10, 9), (5, 4), (1, 0))

    subtractionValues.foldLeft(digitValue) { case (acc, (_, subValue)) =>
      val (index, value) = acc.zipWithIndex.maxBy(_._1)
      if (index > 0 && acc(index - 1) >= subValue) {
        acc.updated(index, acc(index) - subValue) ++ acc.take(index - 1)
      } else acc.updated(index, acc(index) - subValue) ++ acc.drop(index + 1)
    }
  }.map(BigInteger(_)).sum

  override def toDecimal: BigInteger = decimalValue
}

object RomanNumeralConverter {
  def apply(merkmal: Int, value: String): RomanNumeral = {
    merkmal match {
      case 1 => new RomanNumeralM1(value)
      case 2 => new RomanNumeralM2(value)
      case 3 | 4 | 5 => new RomanNumeralM3_5(value)
      case _ => throw new RuntimeException("Kein gültiges Merkmal gewählt")
    }
  }

  def analyse(data: List[List[String]]): List[RomanNumeral] = {
    data.map { row =>
      RomanNumeralConverter(1, row(0)).toDecimal ::
      RomanNumeralConverter(2, row(1)).toDecimal ::
      RomanNumeralConverter(3, row(2)).toDecimal ::
      RomanNumeralConverter(4, row(3)).toDecimal ::
      RomanNumeralConverter(5, row(4))
    }.map(RomanNumeral.apply)
  }
}
