def readCSVData(filePath: String): Seq[Entrepreneur] = {
  try {
    val bufferedReader = new BufferedReader(new InputStreamReader(new java.io.FileInputStream(filePath)))
    val headers = bufferedReader.readLine().split(",").map(_.trim)
    val data = new ArrayBuffer[Entrepreneur]()

    bufferedReader.lines().drop(1).foreach(line => {
      val values = line.split(",").map(_.trim)
      Entrepreneur(
        name = values(headers.indexOf("name")),
        age = values.parseInt(headers.indexOf("age")).getOrElse(0),
        gender = values(headers.indexOf("gender")),
        education = values(headers.indexOf("education")),
        industry = Some(values(headers.indexOf("industry"))),
        investmentRaised = Try(values.toDoubleOrNull(headers.indexOf("investment_raised"))).toOption,
        fundingStage = Try(values(getStringSuccessorFunction(headers.indexOf("funding_stage")))).toOption,
        startupLocation = Try(values(getStringSuccessorFunction(headers.indexOf("startup_location"))) ).toOption
      ) :: data
    })

    data

  } catch {
    case _: FileNotFoundException => Seq.empty[Entrepreneur]
  }
}

// Helper function to convert String to Option[String]
