// Function to extract top 5 key features by considering data variety
def extractTopFeatures(data: Seq[Entrepreneur]): (String, String, String, String, Double) = {
  // Step 1: Flatten company and fundingRound datasets
  val flatterData = data.flatMap { entrepreneur =>
    entrepreneur.industry.map { industry =>
      entrepreneur.compagnies.map { company =>
        (company.name, company.foundedYear, industry, entrepreneur.investmentRaised, entrepreneur)
      } ++
      entrepreneur.fundingRounds.map { fundingRound =>
        (fundingRound.round, fundingRound.amountRaised, fundingRound.investors, entrepreneur)
      }
    }
  }

  // Step 2: Aggregating counts of categories to find popular values
  val industryCounts = flatterData.groupBy(_._3).mapValues(_.size)
  val fundingStageCounts = flatterData.groupBy(_._1).mapValues(_.size)

  // Step 3: Selecting top 5 categories based on counts
  val topIndustry = industryCounts.maxBy(_._2)._1
  val topFundingStage = fundingStageCounts.maxBy(_._2)._1

  // Step 4: Calculating average investment raised by industry
  val groupedInvestmentData = flatterData.groupBy(_._3).mapValues(data => data.map(_._4).sum / data.length)
  val averageInvestmentByIndustry = groupedInvestmentData(topIndustry)

  // Step 5: Grouping data based on industry and calculating median revenue
  val groupedRevenueData = flatterData.groupBy(_._3).mapValues(data => data.filter(_._4.nonEmpty).map(_._5).sorted)

  val medianRevenueByIndustry = groupedRevenueData(topIndustry).map(_._4.median)

  (topIndustry, topFundingStage, entrepreneur.gender.headOption.getOrElse("Unknown"), entrepreneur.education.headOption.getOrElse("Unknown"), averageInvestmentByIndustry)

}

