3. Create a `server.ts` file to define your express server:

   ```typescript
   import express from "express";

   const app = express();

   // define routes and endpoints

   app.listen(3000, () => {
     console.log("Server listening on port 3000");
   });
   ```

4. Create a `main.ts` file to orchestrate your application:

   ```typescript
   import "reflect-metadata";
   import "express-async-errors";
   import express, { Request, Response } from "express";
   import { container } from "tsyringe";
   import { routes } from "./routes";
   import middleware from "./middleware";

   const app = express();

   // load middleware
   app.use(middleware);

   // load express routes
   app.use(routes);

   // start server
   const start = async () => {
     try {
       await app.listen(process.env.PORT);
       console.log(`Server listening on port ${process.env.PORT}`);
     } catch (err) {
       console.error(err);
       process.exit(1);
     }
   };

   export const init = async () => {
     // container configuration (e.g. Dependency injection) comes here

     await start();
   };

   void init();
   ```

5. Create a `routes` folder, and inside it, add `.ts` files defining your routes and controllers:

   ```
   routes
   ├── users.ts
   ├── auth.ts
   ```

6. Write your route definitions and controllers:

   ```
   // users.ts

   import express, { Request, Response } from "express";
   import { container } from "tsyringe";
   import { UsersController } from "../controllers/users";

   const router = express.Router();

   router.get("/", (req: Request, res: Response) => {
     container.resolve<UsersController>(UsersController).index(req, res);
   });

   export default router;
   ```

   ```
   // auth.ts

   import express, { Request, Response } from "express";
   import { container } from "tsyringe";
   import { AuthController } from "../controllers/auth";

   const router = express.Router();

   router.post("/login", (req: Request, res: Response) => {
     container.resolve<AuthController>(AuthController).login(req, res);
   });

   export default router;
   ```

7. Create a `controllers` folder, and inside it, add `.ts` files defining your controllers:

   ```
   controllers
   ├── users.ts
   ├── auth.ts
   ```

8. Write your controller methods:

   ```
   // users.ts

   import { controller, get } from "express-api-decorators";
   import { container } from "tsyringe";
   import { UsersRepository } from "../repositories";
   import { IUser, User } from "../models";

   @controller("/users")
   export default class UsersController {
     private usersRepository: UsersRepository;

     constructor() {
       this.usersRepository = container.resolve(UsersRepository);
     }

     @get()
     async index(_: Request, res: Response) {
       try {
         const users: IUser[] = await this.usersRepository.findAll();
         res.status(200).json(users);
       } catch (err) {
         res.status(500).json({ error: err.message });
       }
     }
   }
   ```

   ```
   // auth.ts

   import { controller, post } from "express-api-decorators";
   import { container } from "tsyringe";
   import { AuthRepository } from "../repositories";
   import { IUser } from "../models";

   @controller("/auth")
   export default class AuthController {
     private authRepository: AuthRepository;

     constructor() {
       this.authRepository = container.resolve(AuthRepository);
     }

     @post("/login")
     async login(req: Request, res: Response) {
       try {
         const { email, password } = req.body;
         const user: IUser = await this.authRepository.authenticate(email, password);
         if (!user) {
           return res.status(401).json({ message: "Invalid email or password" });
         }
         res.status(200).json(user);
       } catch (err) {
         res.status(500).json({ error: err.message });
       }
     }
   }
   ```

9. Create a `middleware` folder, and inside it, add `.ts` files defining your middleware:

   ```
   middleware
   ├── error.ts
