2. Erstellen einer Regel-Datei `vue-update-lifecycle-hooks.js` in einem Ordner namens `rules` im Stammpfad Ihres Projekts.

```javascript
module.exports = {
  "vue-update-lifecycle-hooks": {
    "meta": {
      "type": "problem",
      "fixable": "code",
      "docs": {
        "description": "Warns when updated Lifecycle Hooks methods modify internal component state or call other methods that modify internal component state.",
        "category": "Best Practices",
        "recommended": true
      }
    },

    "create": function(context) {
      let updatedLifeCycleHooks = ["beforeCreate", "created", "beforeMount", "mounted", "beforeUpdate", "updated", "activated", "deactivated", "beforeDestroy", "destroyed", "errorCaptured"];

      return {
        "MemberExpression": function(node) {
          // check if the node is a method call in one of the updated Lifecycle Hooks
          const methodName = node.callee.name;
          const parentNode = node.parent;

          if (updatedLifeCycleHooks.includes(methodName) && parentNode.type === "CallExpression") {
            const callerName = parentNode.callee.name;

            // check if the method call modifies internal component state or call other methods with this behavior
            if (
              methodName === "created" ||
              (methodName === "beforeDestroy" && callerName === "forceUpdate") ||
              (methodName === "destroyed" && callerName === "forceUpdate") ||
              methodName === "errorCaptured" ||
              !!context.options.parser.get(node).expression.type === "MemberExpression" &&
              /\b(set|push|splice)\b/.test(node.object.name) ||
              /_\s*data/.test(context.getAncestorByType(node, "Property")[0].value)
            ) {
              context.report({
                node,
                message: "Updated Lifecycle Hook method '{{ methodName }}' modifies internal component state or calls a method that modifies internal component state.",
                data: { methodName }
              });
            }
          }
        }
      };
    }
  }
};
```

