  extends: ['plugin:vue/recommended'],
  plugins: ['vue-eslint-blocks'],
  rules: {
    // Custom rule for checking updated Lifecycle Hook Methods
    'vue-custom-lifecycle-hook': {
      meta: {
        fixable: 'code',
        docs: {
          description: 'Prevent modifications to internal component state using Lifecycle Hook Methods',
          category: 'Vue.js',
          recommended: true,
        },
        schema: [],
      },
      create(context) {
        return {
          // Check for updated Lifecycle Hook Method calls
          'Property["value"].callee.name': (node) => {
            // Get the name of the Lifecycle Hook Method being called
            const methodName = node.callee.name;

            // Ignore built-in methods that modify internal state
            if (
              methodName === 'push' ||
              methodName === 'splice' ||
              methodName === 'sort' ||
              methodName === 'reverse' ||
              methodName === 'shift' ||
              methodName === 'unshift' ||
              methodName === 'pop'
            ) {
              return;
            }

            // Check if the method modifies internal state (e.g. $data or $props)
            const methodNameModifier = methodName.startsWith('$');
            const methodNameRoot = methodName.slice(1);

            // Ignore built-in properties (e.g. $attrs, $listeners)
            if (
              Object.prototype.hasOwnProperty.call(
                Vue.prototype,
                methodNameRoot
              ) ||
              (methodName === '$set' && node.arguments.length !== 2)
            ) {
              return;
            }

            // Report if updated Lifecycle Hook Methods modify internal state
            if (
              node.parent.type === 'CallExpression' &&
              node.parent.arguments.length === 1 &&
              node.parent.arguments[0].type === 'ObjectExpression' &&
              methodNameModifier
            ) {
              context.report({
                node,
                message: `Updated Lifecycle Hook Method "${methodName}" modifies internal component state. Please use computed properties or methods instead.`,
                fix(fixer) {
                  // Replace the updated Lifecycle Hook Method with a computed property
                  return fixer.replaceText(node, `computed: { [methodName] () { return ${methodNameRoot}; } }`);
                },
              });
            } else if (
              methodName === '$forceUpdate' ||
              methodName === '$nextTick' ||
              methodName === '$watch' ||
              methodName === '$on' ||
              methodName === '$off'
            ) {
              context.report({
                node,
                message: `Updated Lifecycle Hook Method "${methodName}" directly modifies internal component state. Please use computed properties or methods instead.`,
              });
            }
          },
        };
      },
    },
  },
};
